/** Actual private widgets only; no runtime actor, journal, placement or canonical claim. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeRampScreenChecks {
 private static NativeRampBlock full,slab;private static BlockEntityType<NativeRampEntity> type;private static MenuType<NativeRampMenu> menuType;
 private static NativeRampScreen screen;private static int index,ticks,stage,checks,frames;private static boolean captured;private static String capture;
 private static java.util.concurrent.CompletableFuture<Void> reload;private static final List<RampSettingsPayload> edits=new ArrayList<>();
 private static boolean enabled(){return Boolean.getBoolean("vandorlabs.rampScreenCheck");}
 @EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{full=new NativeRampBlock(BlockBehaviour.Properties.of(),()->type);slab=new NativeRampSlabBlock(BlockBehaviour.Properties.of(),()->type);h.register(ResourceLocation.parse("vandorlabs:ramp_screen_full"),full);h.register(ResourceLocation.parse("vandorlabs:ramp_screen_slab"),slab);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeRampEntity>of((pos,state)->new NativeRampEntity(type,pos,state,state.is(slab)),full,slab).build(null);h.register(ResourceLocation.parse("vandorlabs:ramp_screen_fixture"),type);});event.register(Registries.MENU,h->{menuType=new MenuType<>((id,inventory)->{throw new UnsupportedOperationException("Title-only editor");},net.minecraft.world.flag.FeatureFlags.VANILLA_SET);h.register(ResourceLocation.parse("vandorlabs:ramp_screen_fixture"),menuType);});}
 }
 private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Ramp widgets index="+index+" stage="+stage+": "+text);}
 private static void click(int id,int button){var widget=screen.button(id);need(widget!=null&&widget.active,"available control "+id);need(screen.mouseClicked(widget.getX()+widget.getWidth()/2D,widget.getY()+widget.getHeight()/2D,button),"actual click "+id);}
 private static void create(Minecraft mc){edits.clear();var scan=Direction.from3DDataValue(index%6);var block=index<6?full:slab;var state=block.defaultBlockState().setValue(NativeRampBlock.ACTIVE_FACE,scan).setValue(NativeRampBlock.FACING,scan.getAxis().isHorizontal()?scan:Direction.EAST);var owner=(NativeRampEntity)block.newBlockEntity(BlockPos.ZERO,state);var status=new NativeRampMenu.Status("Retracted",false,false,false,0);var menu=new NativeRampMenu(menuType,37,owner,owner.scanFacing(),owner.horizontalFacing(),(player,next)->{throw new AssertionError("Title must not invoke a runtime command");},()->status);screen=new NativeRampScreen(menu,new Inventory(null),Component.literal(index<6?"Ramp Controller":"Ramp Controller Slab"),edits::add);screen.init(mc,640,360);need(screen.page()==0&&screen.editingDraft().settings().resolvedDirection(owner.horizontalFacing().get3DDataValue())==owner.horizontalFacing().get3DDataValue(),"separate scan/travel initial context");click(1,1);need(screen.editingDraft().mode()==6,"reverse mode wraps Moat");click(1,0);need(screen.editingDraft().mode()==0,"forward mode wraps ramp");
  for(int i=1;i<=4;i++)click(1,0);need(screen.editingDraft().mode()==4&&!screen.startSlider().active&&screen.editingDraft().settings().startHalf()==0,"escalator mode resets start and disables slider");click(31,0);need(!screen.button(22).active,"escalator disables analog choice");click(30,0);for(int i=0;i<4;i++)click(1,1);need(screen.editingDraft().mode()==0,"previous modes return ramp");
  int before=edits.size();need(screen.mouseClicked(screen.endSlider().getX()+screen.endSlider().getWidth()-1,screen.endSlider().getY()+8,0),"end slider press");screen.mouseDragged(screen.endSlider().getX()+screen.endSlider().getWidth()-1,screen.endSlider().getY()+8,0,100,0);need(edits.size()==before,"Source sliders wait for release");screen.mouseReleased(0,0,0);need(edits.size()==before+1&&edits.getLast().edit().settings().endHalf()==32,"half-offset release exact maximum");screen.mouseReleased(0,0,0);need(edits.size()==before+1,"unchanged release no duplicate");
  screen.treadField().setValue("3");before=edits.size();click(4,0);need(edits.size()==before&&screen.treadField().getValue().equals("3"),"invalid nonpower tread draft refuses options");click(31,0);screen.channelField().setValue("31, 32");need(edits.size()==before,"invalid hidden tread refuses channel edit");click(30,0);screen.treadField().setValue("4");need(edits.size()==before+1&&edits.getLast().edit().settings().channels().size()==2,"next valid draft emits complete retained choices before="+before+" actual="+edits.size()+" last="+(edits.isEmpty()?null:edits.getLast())+" tread="+screen.treadField().getValue());click(14,0);need(screen.treadField().getValue().equals("2"),"Source tread step down");click(15,0);need(screen.treadField().getValue().equals("4"),"Source tread step up");
  click(31,0);screen.channelField().setValue("31,");before=edits.size();click(3,1);need(edits.size()==before,"invalid channels refuse activation");click(30,0);click(18,1);need(edits.size()==before,"invalid hidden channel draft refuses match option");click(31,0);need(screen.channelField().getValue().equals("31,"),"invalid channel draft survives tabs");screen.channelField().setValue("31, 32");need(edits.size()==before+1,"valid channels publish once");screen.channelField().setValue("letters");need(screen.channelField().getValue().equals("31, 32"),"Source character filter");click(22,1);need(screen.editingDraft().settings().analogDeployment()&&!owner.settings().analogDeployment(),"live analog remains draft without runtime side effects");var last=edits.getLast().edit();var initial=menu.draft().settings();var error=new NativeRampMenu.Status("Reset blocked: clear the original platform position",true,false,false,0);screen.acknowledge(new RampSettingsPayload.Result(new NativeRampEdit(BlockPos.ZERO,37,last.request()-1,initial),error,false,false,false,true));need(!screen.displayedStatus().error(),"stale response ignored");var pending=new NativeRampMenu.Status("Saving Ramp recovery journal",false,true,false,0);screen.acknowledge(new RampSettingsPayload.Result(new NativeRampEdit(BlockPos.ZERO,37,last.request(),initial),pending,true,false,true,false));need(screen.displayedStatus().pending()&&screen.editingDraft().settings().analogDeployment(),"pending operation preserves draft and is not rejected");screen.acknowledge(new RampSettingsPayload.Result(new NativeRampEdit(BlockPos.ZERO,37,last.request(),initial),error,true,false,false,true));need(screen.displayedStatus().error()&&!screen.editingDraft().settings().analogDeployment()&&screen.channelField().getValue().equals("31, 32"),"rejected reset restores server choices but preserves channel text");
  click(30,0);screen.init(mc,320,240);for(int id:new int[]{1,4,6,7,14,15,17,18,19,24,30,31}){var widget=screen.button(id);need(widget.getX()>=0&&widget.getX()+widget.getWidth()<=320&&widget.getY()>=0&&widget.getY()+widget.getHeight()<=240,"compact control bounds "+id);}capture="ramp-editor-"+index+".png";captured=false;frames=0;
 }
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!enabled()||stage==9)return;var mc=Minecraft.getInstance();try{if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}need(++ticks<2600,"title timeout");if(ticks<80||mc.getOverlay()!=null||!(mc.screen instanceof TitleScreen))return;need(mc.level==null&&mc.getSingleplayerServer()==null,"title-only no world/runtime");if(stage==0){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();create(mc);stage=1;}else if(stage==1&&captured){if(++index<12)create(mc);else{reload=mc.reloadResourcePacks();stage=2;}}else if(stage==2&&reload.isDone()){reload.join();screen.init(mc,640,360);need(screen.channelField()==null&&screen.displayedStatus().error(),"reload preserves page/rejection status");capture="ramp-editor-reloaded.png";captured=false;frames=0;stage=3;}else if(stage==3&&captured){System.out.println("[vandorlabs][ramp-screen] title PASS checks="+checks+" profiles=12 full/slab/sixScanFaces reverse7modes sliders tread channels hiddenInvalid pendingErrorAck compact reload; no runtime claim");stage=9;mc.stop();}}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][ramp-screen] FAIL "+failure);stage=9;mc.stop();}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||screen==null||!(event.getScreen() instanceof TitleScreen)||Minecraft.getInstance().getOverlay()!=null)return;var g=event.getGuiGraphics();g.flush();g.pose().pushPose();try{g.pose().translate(0,0,300);g.fill(0,0,640,360,0xFF101012);screen.render(g,0,0,0);g.flush();frames++;}finally{g.pose().popPose();}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!enabled()||capture==null||frames<6)return;String name=capture;capture=null;var mc=Minecraft.getInstance();Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),ignored->captured=true);}
}
